package com.bendemenstudios.steampunksync.client;
import com.bendemenstudios.steampunksync.model.VersionManifest; import net.minecraft.client.gui.GuiGraphics; import net.minecraft.client.gui.components.Button; import net.minecraft.client.gui.screens.Screen; import net.minecraft.network.chat.Component;
public final class SteampunkSyncScreen extends Screen {private final VersionManifest m;private volatile long done,total;private volatile String status="Ready to update";private volatile boolean running;public SteampunkSyncScreen(VersionManifest m){super(Component.literal("SteampunkSync"));this.m=m;}protected void init(){addRenderableWidget(Button.builder(Component.literal("UPDATE NOW"),b->start()).bounds(width/2-80,height/2+55,160,20).build());}private void start(){if(running)return;running=true;status="Starting...";Thread.startVirtualThread(()->{SyncResult r=PackSynchronizer.downloadAndInstall(m,minecraft.gameDirectory.toPath(),(d,t,s)->{done=d;total=t;status=s;});minecraft.execute(()->{running=false;status=r.message();if(r.success())ClientUpdateState.setInstalledVersion(m.version());});});}public void render(GuiGraphics g,int mx,int my,float pt){renderBackground(g,mx,my,pt);int cx=width/2;g.drawCenteredString(font,"STEAMPUNK SYNC",cx,height/2-75,0xFFD18A45);g.drawCenteredString(font,m.modpack()+" • "+m.version(),cx,height/2-52,0xFFFFFFFF);g.drawCenteredString(font,"New modpack version available",cx,height/2-30,0xFFC0C0C0);int x=cx-130,y=height/2+25,w=260;g.fill(x,y,x+w,y+8,0xFF29231D);if(total>0)g.fill(x,y,x+(int)Math.min(w,done*w/total),y+8,0xFFD18A45);g.drawCenteredString(font,status,cx,y+18,0xFFFFFFFF);super.render(g,mx,my,pt);}public boolean shouldCloseOnEsc(){return !running;}}
